import { z } from 'zod';import { getDb } from '../../../../../lib/db';import { getSession } from '../../../../../lib/session';import { jsonError,jsonOk,readJson } from '../../../../../lib/http';
const schema=z.object({approved:z.boolean(),commissionPercent:z.number().min(0).max(50).optional()});
export async function PATCH(request,{params}){const user=await getSession();if(!user)return jsonError('Please sign in.',401);if(user.role!=='ADMIN')return jsonError('Admin access required.',403);const parsed=schema.safeParse(await readJson(request));if(!parsed.success)return jsonError('Invalid vendor update.');const {id}=await params;try{const db=getDb();const [result]=await db.execute(parsed.data.commissionPercent===undefined?'UPDATE vendors SET approved=? WHERE id=?':'UPDATE vendors SET approved=?,commission_percent=? WHERE id=?',parsed.data.commissionPercent===undefined?[parsed.data.approved?1:0,id]:[parsed.data.approved?1:0,parsed.data.commissionPercent,id]);if(!result.affectedRows)return jsonError('Vendor not found.',404);return jsonOk({ok:true});}catch(e){console.error('Vendor approval error:',e);return jsonError('Could not update vendor.',500);}}
